import type { LessonContent, Mark, TraceStep } from '../schema';

const code = String.raw;

/**
 * PL17 虛擬機、位元組碼與 JIT. Every example and the reference solutions run in tests/curriculum-code.test.ts (C++17,
 * Java 17, Python 3, Node.js); the exercise's expected outputs were generated by running the four reference solutions,
 * which agree on every case. Real `javap -c`, `dis.dis` and `node --print-bytecode` listings change between versions,
 * so they appear only in the prose as illustrations. JIT compilation is shown only as a deterministic simulation (a call
 * counter, a type guard and deoptimization); nothing measures time, and performance claims give direction and reason.
 *
 * The stack-queue trace is produced by vmSteps below, which runs TRACE_PROGRAM with the same rules as the traced Python
 * VM (and as the exercise): one step per executed instruction, with pc, the operand stack and the local-variable slots.
 */

// ---- the traced VM --------------------------------------------------------------------------------------------------
type TraceOp = 'PUSH' | 'LOAD' | 'STORE' | 'ADD' | 'SUB' | 'JMP' | 'JZ' | 'PRINT' | 'HALT';
interface TraceInstr { op: TraceOp; arg?: number; comment?: string }

/** total = 3 + 2 + 1, compiled by hand from `n = 3; total = 0; while n != 0: total += n; n -= 1; print(total)`. */
export const TRACE_PROGRAM: TraceInstr[] = [
  { op: 'PUSH', arg: 3, comment: 'n = 3' },
  { op: 'STORE', arg: 0 },
  { op: 'PUSH', arg: 0, comment: 'total = 0' },
  { op: 'STORE', arg: 1 },
  { op: 'LOAD', arg: 0, comment: '迴圈開頭' },
  { op: 'JZ', arg: 15, comment: 'n == 0 就跳出迴圈' },
  { op: 'LOAD', arg: 1 },
  { op: 'LOAD', arg: 0 },
  { op: 'ADD', comment: 'total + n' },
  { op: 'STORE', arg: 1 },
  { op: 'LOAD', arg: 0 },
  { op: 'PUSH', arg: 1 },
  { op: 'SUB', comment: 'n - 1' },
  { op: 'STORE', arg: 0 },
  { op: 'JMP', arg: 4, comment: '回到迴圈開頭' },
  { op: 'LOAD', arg: 1 },
  { op: 'PRINT' },
  { op: 'HALT' },
];
export const TRACE_SLOTS = ['n', 'total'];
const show = (i: TraceInstr) => i.arg === undefined ? i.op : `${i.op} ${i.arg}`;

/** The VM loop of the traced Python program; the instruction at pc is on line pc + 2 (the list starts on line 2). */
const VM_LOOP = code`]
stack, slots, pc = [], [0, 0], 0     # 槽 0 是 n，槽 1 是 total
while True:
    op, arg = program[pc]            # 取指（fetch）
    pc += 1
    if op == "PUSH":                 # 解碼（decode）並執行（execute）
        stack.append(arg)
    elif op == "LOAD":
        stack.append(slots[arg])
    elif op == "STORE":
        slots[arg] = stack.pop()
    elif op in ("ADD", "SUB"):
        b = stack.pop()              # 先彈出的是右運算元
        a = stack.pop()
        stack.append(a + b if op == "ADD" else a - b)
    elif op == "JMP":
        pc = arg
    elif op == "JZ":
        if stack.pop() == 0:
            pc = arg
    elif op == "PRINT":
        print(stack.pop())
    elif op == "HALT":
        break`;

/** The traced program: the bytecode list built from TRACE_PROGRAM (so the two cannot differ), then the VM loop. */
export const VM_TRACE_PY = ['program = [',
  ...TRACE_PROGRAM.map((ins, pc) => `    ("${ins.op}", ${ins.arg ?? 'None'}),`.padEnd(21) + `# ${pc}${ins.comment ? `: ${ins.comment}` : ''}`),
  VM_LOOP].join('\n');

/**
 * Runs a program with the traced VM's rules and records one step per executed instruction: the line of the instruction
 * (pc + 2), pc and the instruction, the operand stack after it, the local-variable slots and everything printed so far.
 */
export function vmSteps(program: TraceInstr[], slotNames: string[]): TraceStep[] {
  const stack: number[] = [], slots = slotNames.map(() => 0), printed: string[] = [], steps: TraceStep[] = [];
  const slot = (k: number) => `槽 ${k}（${slotNames[k]}）`;
  let pc = 0, executed = 0;
  for (;;) {
    const ins = program[pc], at = pc, arg = ins.arg ?? 0;
    let next = pc + 1, note = '', pushed = false;
    let slotMark: { row: number; kind: Mark } | undefined;
    executed++;
    switch (ins.op) {
      case 'PUSH': stack.push(arg); pushed = true; note = `把常數 ${arg} 推上運算元堆疊。`; break;
      case 'LOAD': stack.push(slots[arg]); pushed = true; slotMark = { row: arg, kind: 'read' };
        note = `讀取${slot(arg)}的值 ${slots[arg]}，推上堆疊；槽裡的值不變。`; break;
      case 'STORE': { const v = stack.pop()!; slots[arg] = v; slotMark = { row: arg, kind: 'write' };
        note = `彈出堆疊頂端的 ${v}，存進${slot(arg)}。STORE 會消耗堆疊上的值，所以堆疊少了一格。`; break; }
      case 'ADD': case 'SUB': { const b = stack.pop()!, a = stack.pop()!, r = ins.op === 'ADD' ? a + b : a - b;
        stack.push(r); pushed = true;
        note = `先彈出右運算元 ${b}，再彈出左運算元 ${a}，計算 ${a} ${ins.op === 'ADD' ? '+' : '-'} ${b} = ${r}，把結果推回堆疊：兩個進、一個出。`; break; }
      case 'JMP': next = arg; note = `無條件跳躍：把 pc 設為 ${arg}，回到迴圈開頭再檢查一次 n。`; break;
      case 'JZ': { const v = stack.pop()!; if (v === 0) next = arg;
        note = v === 0 ? `彈出 ${v}，等於 0，跳到 pc ${arg}：迴圈結束。` : `彈出 ${v}，不是 0，不跳躍：pc 前進到 ${next}，執行迴圈本體。`; break; }
      case 'PRINT': { const v = stack.pop()!; printed.push(String(v)); note = `彈出 ${v} 並印出。`; break; }
      case 'HALT': note = `HALT：VM 停止。總共執行了 ${executed} 條指令，其中迴圈本體（pc 4～14）每一輪 11 條；n 越大，迴圈的指令就越多，這正是 JIT 想找出來的熱點。`; break;
    }
    if (at === 0) note = `VM 從 pc 0 開始，每一圈做三件事：取出 pc 指到的指令（fetch）、看它是哪一種（decode）、執行它（execute），然後 pc 前進到下一條。${note}`;
    steps.push({
      line: at + 2, note,
      vars: { pc: String(at), 指令: show(ins), '下一個 pc': ins.op === 'HALT' ? '（停止）' : String(next), 已執行指令數: String(executed) },
      containers: [{ name: '運算元堆疊', kind: 'stack', items: stack.map(String), marks: pushed ? [{ at: stack.length - 1, kind: 'write' }] : [] }],
      table: { name: '區域變數槽', head: ['槽', '名稱', '值'], rows: slots.map((v, k) => [String(k), slotNames[k], String(v)]), marks: slotMark ? [slotMark] : [] },
      ...(printed.length ? { output: printed.join('\n') } : {}),
    });
    if (ins.op === 'HALT') break;
    pc = next;
  }
  return steps;
}

